/* ============================================================================
   1. Sharp Wallpaper Backdrop + Dynamic Scrim (rendered on html::before & body::before)
   ============================================================================ */
html {
  background-color: rgb(var(--kn-d-chrome-rgb, 23, 20, 33)) !important;
  overflow: clip !important;
}

html:has(> body.theme-light, > body > .monaco-workbench:is(.vs:not(.vs-dark), .hc-light)) {
  background-color: rgb(var(--kn-l-chrome-rgb, 243, 228, 234)) !important;
}

html::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 0 !important;
  pointer-events: none;
  will-change: transform, filter;
  transform: translateZ(0) scale(var(--kn-wp-scale, 1));
  filter: var(--kn-wp-filter, none);
  opacity: var(--kn-wp-opacity, 1);
  background-size: var(--kn-wp-size, cover);
  background-position: var(--kn-wp-pos, center top);
  background-repeat: no-repeat;
}

html:has(> body.theme-light, > body > .monaco-workbench:is(.vs:not(.vs-dark), .hc-light))::before {
  background-position: var(--kn-wp-pos-light, var(--kn-wp-pos, center top));
}

body {
  background: transparent !important;
  color: var(--foreground) !important;
}

body::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 0 !important;
  pointer-events: none;
  will-change: transform;
  transform: translateZ(0);
  opacity: var(--kn-scrim-opacity, 0.75);
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}

